import{_ as i,o as l,c as d,a2 as t}from"./chunks/framework.DJWFW3S-.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/includes/api/geometry-methods.md","filePath":"api/includes/api/geometry-methods.md"}'),o={name:"api/includes/api/geometry-methods.md"};function a(r,e,s,p,m,u){return l(),d("div",null,[...e[0]||(e[0]=[t("<details><summary>getFirstCoordinate()</summary><div><br><p>获取几何图形第一个坐标点</p><p>返回：</p><ul><li><code>Coordinate</code> First Coordinate</li></ul></div></details><details><summary>getLastCoordinate()</summary><div><br><p>获取几何图形最后一个坐标点</p><p>返回：</p><ul><li><code>Coordinate</code> Last Coordinate</li></ul></div></details><details><summary>addTo(layer, fitview?)</summary><div><br><p>将几何图形添加到指定图层上</p><p>参数：</p><ul><li>layer <code>OverlayLayer</code> layer add to</li><li>fitview（可选） <code>boolean | addGeometryFitViewOptions</code> =false] - automatically set the map to a fit center and zoom for the geometry</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#add</code></li></ul></div></details><details><summary>getLayer()</summary><div><br><p>获取几何图形所在的图层</p><p>返回：</p><ul><li><code>Layer</code> - layer added to</li></ul></div></details><details><summary>getMap()</summary><div><br><p>获取几何图形所在的地图对象</p><p>返回：</p><ul><li><code>Map</code> - map added to</li></ul></div></details><details><summary>getId()</summary><div><br><p>获取几何图形的id</p><p>返回：</p><ul><li><code>String|Number</code> geometry的id</li></ul></div></details><details><summary>setId(id)</summary><div><br><p>给几何图形设置id</p><p>参数：</p><ul><li>id <code>string</code> new id</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#idchange</code></li></ul></div></details><details><summary>getProperties()</summary><div><br><p>获取几何图形的属性</p><p>返回：</p><ul><li><code>Object</code> properties</li></ul></div></details><details><summary>setProperties(properties)</summary><div><br><p>给几何图形设置新的属性 Set a new properties to geometry.</p><p>参数：</p><ul><li>properties <code>{ [key: string]: any }</code> new properties</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#propertieschange</code></li></ul></div></details><details><summary>getType()</summary><div><br><p>获取几何图形的类型,例如“点”,&quot;线&quot;</p><p>返回：</p><ul><li><code>String</code> type of the geometry</li></ul></div></details><details><summary>getSymbol()</summary><div><br><p>获取几何图形的样式</p><p>返回：</p><ul><li><code>Object</code> geometry&#39;s symbol</li></ul></div></details><details><summary>setSymbol(symbol)</summary><div><br><p>给几何图形设置样式</p><p>参数：</p><ul><li>symbol <code>any</code> new symbol</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#symbolchange</code></li></ul></div></details><details><summary>getSymbolHash()</summary><div><br><p>获取样式的哈希值</p><p>返回：</p><ul><li><code>String</code></li></ul></div></details><details><summary>updateSymbol(props)</summary><div><br><p>更新几何图形当前的样式</p><p>参数：</p><ul><li>props <code>any</code> symbol properties to update</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#symbolchange</code></li></ul></div></details><details><summary>getTextContent()</summary><div><br><p>如果几何图形有文本内容，就获取它</p><p>返回：</p><ul><li><code>String</code></li></ul></div></details><details><summary>getTextDesc()</summary><div><br><p>获取文本描述，由文本内容与 sizeSymbol 计算并缓存</p><p>返回：</p><ul><li><code>any</code></li></ul></div></details><details><summary>getCenter()</summary><div><br><p>获取几何图形中心点</p><p>返回：</p><ul><li><code>Coordinate</code></li></ul></div></details><details><summary>getExtent()</summary><div><br><p>获取几何图形的包围盒范围</p><p>返回：</p><ul><li><code>Extent</code> geometry&#39;s extent</li></ul></div></details><details><summary>getContainerExtent(out?)</summary><div><br><p>获取几何图形的屏幕像素范围</p><p>参数：</p><ul><li>out（可选） <code>PointExtent</code></li></ul><p>返回：</p><ul><li><code>PointExtent</code></li></ul></div></details><details><summary>get2DExtent()</summary><div><br><p>获取当前 zoom 下几何体的 2D 像素 extent</p><p>返回：</p><ul><li><code>PointExtent</code></li></ul></div></details><details><summary>getSize()</summary><div><br><p>获取几何体的像素大小，不同缩放级别的像素大小可能会有所不同。</p><p>返回：</p><ul><li><code>Size</code></li></ul></div></details><details><summary>containsPoint(containerPoint, t?)</summary><div><br><p>几何体是否包含输入容器点</p><p>参数：</p><ul><li>containerPoint <code>Point</code> input container point or coordinate</li><li>t（可选） <code>number</code> =undefined] - tolerance in pixel</li></ul><p>返回：</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>show()</summary><div><br><p>显示几何图形</p><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#show</code></li></ul></div></details><details><summary>hide()</summary><div><br><p>隐藏几何图形</p><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#hide</code></li></ul></div></details><details><summary>isVisible()</summary><div><br><p>几何图形是否可见</p><p>返回：</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>symbolIsVisible()</summary><div><br><p>symbol是否可见</p><p>返回：</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>getZIndex()</summary><div><br><p>获取几何图形所在层级，默认是0</p><p>返回：</p><ul><li><code>Number</code> zIndex</li></ul></div></details><details><summary>setZIndex(zIndex)</summary><div><br><p>给几何图形设置新的层级并触发zindexchange事件（将导致层对几何体进行排序并进行渲染）</p><p>参数：</p><ul><li>zIndex <code>number</code> new zIndex</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#zindexchange</code></li></ul></div></details><details><summary>setZIndexSilently(zIndex)</summary><div><br><p>仅将新的zIndex设置为Geometry，而不触发zindexchange事件 当需要更新许多几何图形的zIndex时，可以用来提高性能 当更新了N个几何体时，可以将setZIndexSilently与（N-1）个几何体一起使用，并将setZIendex与要排序和渲染的层的最后一个几何体一同使用。</p><p>参数：</p><ul><li>zIndex <code>number</code> new zIndex</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul></div></details><details><summary>bringToFront()</summary><div><br><p>将几何图形至于顶层</p><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#zindexchange</code></li></ul></div></details><details><summary>bringToBack()</summary><div><br><p>将几何图形置于底层</p><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#zindexchange</code></li></ul></div></details><details><summary>translate(x, y?, z?)</summary><div><br><p>按给定偏移量平移几何体的所有 coordinate</p><p>参数：</p><ul><li>x <code>number | Coordinate</code> x offset</li><li>y（可选） <code>number</code> y offset</li><li>z（可选） <code>number</code> z offset</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#positionchange</code></li><li><code>Geometry#shapechange</code></li></ul></div></details><details><summary>flash(interval?, count?, cb?)</summary><div><br><p>闪烁几何图形，按一定的内部显示和隐藏计数次数。</p><p>参数：</p><ul><li>interval（可选） <code>number</code> =100] - interval of flash, in millisecond (ms)</li><li>count（可选） <code>number</code> =4] - flash times</li><li>cb（可选） <code>() =&gt; void, context: any</code> =null] - callback function when flash ended</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul></div></details><details><summary>copy()</summary><div><br><p>返回不包含事件侦听器的几何体的副本。</p><p>返回：</p><ul><li><code>Geometry</code> copy</li></ul></div></details><details><summary>remove()</summary><div><br><p>将其自身从图层中移除（如果有的话）。</p><p>返回：</p><ul><li><code>Geometry</code> this</li></ul><p>触发事件：</p><ul><li><code>Geometry#removestart</code></li><li><code>Geometry#remove</code></li></ul></div></details><details><summary>toGeoJSONGeometry()</summary><div><br><p>将几何对象导出成geojson对象</p><p>返回：</p><ul><li><code>Object</code> GeoJSON Geometry</li></ul></div></details><details><summary>toGeoJSON(opts?)</summary><div><br><p>导出geojson对象中的一个feature</p><p>参数：</p><ul><li>opts（可选） <code>{ [key: string]: any }</code> =null] - export options</li></ul><p>返回：</p><ul><li><code>Object</code> GeoJSON Feature</li></ul></div></details><details><summary>toJSON(options?)</summary><div><br><p>从几何体中导出一个配置文件json。 除了导出特性对象，概要文件json还包含符号、构造选项和信息窗口信息。 配置文件json可以存储在其他地方，稍后用于重现几何图形 由于函数的序列化问题，概要文件json中不包括事件侦听器和上下文菜单</p><p>参数：</p><ul><li>options（可选） <code>{ [key: string]: any }</code> =null] - export options</li></ul><p>返回：</p><ul><li><code>Object</code> profile json object</li></ul></div></details><details><summary>getLength()</summary><div><br><p>获取几何图形的地理长度</p><p>返回：</p><ul><li><code>Number</code> geographic length, unit is meter</li></ul></div></details><details><summary>getArea()</summary><div><br><p>获取几何图形的面积</p><p>返回：</p><ul><li><code>Number</code> geographic area, unit is sq.meter</li></ul></div></details><details><summary>rotate(angle, pivot?)</summary><div><br><p>按给定角度围绕轴心点旋转几何体</p><p>参数：</p><ul><li>angle <code>number</code> angle to rotate in degree</li><li>pivot（可选） <code>Coordinate</code> =null] - optional, will be the geometry&#39;s center by default</li></ul><p>返回：</p><ul><li><code>Geometry</code> this</li></ul></div></details><details><summary>isRotated()</summary><div><br><p>判断几何体是否设置了旋转角与旋转中心</p><p>返回：</p><ul><li><code>boolean</code></li></ul></div></details><details><summary>onHide()</summary><div><br><p>几何体隐藏时关闭已打开的菜单与 infoWindow</p></div></details><details><summary>onShapeChanged()</summary><div><br><p>形状变化时清缓存、重绘并触发 shapechange 事件</p></div></details><details><summary>onPositionChanged()</summary><div><br><p>位置变化时清缓存、重绘并触发 positionchange 事件</p></div></details><details><summary>onSymbolChanged()</summary><div><br><p>symbol 变化时刷新 symbol、重建 sizeSymbol 并触发事件</p></div></details><details><summary>onConfig(conf)</summary><div><br><p>config 更新 options 后的回调，同步 properties 并按需重绘</p><p>参数：</p><ul><li>conf <code>any</code></li></ul></div></details><details><summary>getAltitude()</summary><div><br><p>获取几何体的海拔高度，返回数值或高度数组</p><p>返回：</p><ul><li><code>number | number[] | number[][]</code></li></ul></div></details><details><summary>hasAltitude()</summary><div><br><p>判断几何体是否设置了非零的 altitude</p><p>返回：</p><ul><li><code>boolean</code></li></ul></div></details><details><summary>setAltitude(alt)</summary><div><br><p>设置几何体的 altitude，并同步改写 coordinate 的 z 值</p><p>参数：</p><ul><li>alt <code>number</code></li></ul><p>返回：</p><ul><li><code>this</code></li></ul></div></details><details><summary>getMinAltitude()</summary><div><br><p>获取几何体所有 coordinate 中最小的 altitude</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>getMaxAltitude()</summary><div><br><p>获取几何体所有 coordinate 中最大的 altitude</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>getHoles()</summary><div><br><p>获取面状几何体的孔洞坐标数组，仅部分子类实现</p><p>返回：</p><ul><li><code>Array&lt;Array&lt;Coordinate&gt;&gt;</code></li></ul></div></details><details><summary>getShell()</summary><div><br><p>获取几何体外环的 coordinate 数组，仅部分子类实现</p><p>返回：</p><ul><li><code>Array&lt;Coordinate&gt;</code></li></ul></div></details><details><summary>getGeometries()</summary><div><br><p>获取几何体集合内的子几何体数组，仅集合类子类实现</p><p>返回：</p><ul><li><code>Geometry[]</code></li></ul></div></details><details><summary>getCoordinates()</summary><div><br><p>获取几何体的 coordinate，按类型返回坐标或嵌套数组</p><p>返回：</p><ul><li><code>Coordinate | Array&lt;Coordinate&gt; | Array&lt;Array&lt;Coordinate&gt;&gt; | Array&lt;Array&lt;Array&lt;Coordinate&gt;&gt;&gt;</code></li></ul></div></details><details><summary>setCoordinates(coordinate)</summary><div><br><p>设置几何体的 coordinate 并更新其几何状态</p><p>参数：</p><ul><li>coordinate <code>any</code></li></ul><p>返回：</p><ul><li><code>this</code></li></ul></div></details><details><summary>onRemove()</summary><div><br><p>几何体从 layer 移除时的回调，由框架内部调用</p></div></details><details><summary>getRotateOffsetAngle()</summary><div><br><p>获取几何体按中心旋转时的角度偏移，目前仅 Sector 实现</p><p>返回：</p><ul><li><code>number</code></li></ul></div></details><details><summary>onAdd()</summary><div><br><p>几何体加入 layer 后的回调，由框架内部调用</p></div></details>",60)])])}const y=i(o,[["render",a]]);export{n as __pageData,y as default};
